#include <iostream>
#include <array>
#include <atomic>
#include <cstddef>
#include <vector>
#include <memory>
#include <utility>
struct Pool{std::array<int,2>values{};std::array<bool,2>used{};int*acquire(){for(std::size_t i=0;i<2;++i)if(!used[i]){used[i]=true;return &values[i];}return nullptr;}void release(int*p){std::size_t i=p-values.data();if(i<2)used[i]=false;}};
int main(){
Pool pool;int*a=pool.acquire();pool.release(a);int*b=pool.acquire();std::cout<<(a==b);
}

