struct Pool{std::array<int,1>v{};bool used=false;int*acquire(){if(used)return nullptr;used=true;return &v[0];}void release(int*p){if(p==&v[0])used=false;}};
int main(){
Pool p;int*a=p.acquire();*a=7;p.release(a);int*b=p.acquire();std::cout<<*b;
